{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Indomethacin, an indole/chlorophenyl drug, has approximately 98% absolute oral bioavailability in adults, showing that this general scaffold can be very well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Rigosertib, a methoxy-substituted oncology drug, has 35% absolute oral bioavailability in fasting patients, supporting F ≥ 20% for a similarly polyaromatic, methoxylated molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rigosertib fed-state absolute bioavailability was 13.9%, below the threshold, but this reflects a fed condition and an anionic carboxylate/sulfone structure not present in the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "Omeprazole has about 30–40% absolute oral bioavailability in humans, supporting moderate but above-threshold bioavailability for a heteroaromatic drug with first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Alfuzosin, a methoxy-substituted heteroaromatic drug, has 64% absolute oral bioavailability in healthy volunteers, supporting high bioavailability for a basic heteroaromatic amide-like molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Colchicine, a trimethoxy-substituted aromatic amide, has 44% absolute oral bioavailability in healthy young men, supporting F ≥ 20% for a methoxy-rich aromatic amide.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F ≥ 20%) because multiple structurally related oral drugs show absolute bioavailability values of 30–98%; the only sub-20% evidence is fed-state rigosertib with low transferability to the query.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule is provided.",
    "Fed/fasted conditions and formulation effects for the query are unknown.",
    "Some records are predicted or population-specific rather than direct adult human absolute bioavailability data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

